const ksiazka = { tytul: "Diuna", autor: "Frank Herbert" };
const json = JSON.stringify(ksiazka);
console.log(json, typeof json);
// '{"tytul":"Diuna","autor":"Frank Herbert"}' 'string'

const ksiazka = { tytul: "Diuna", autor: "Frank Herbert" };
console.log(JSON.stringify(ksiazka, null, 2));
// {
//   "tytul": "Diuna",
//   "autor": "Frank Herbert"
// }

const tekst = '{"imie":"Zosia","wiek":9}';
const obiekt = JSON.parse(tekst);
console.log(obiekt.imie); // "Zosia"

const firma = { nazwa: "Techno", adres: { miasto: "Poznan" } };
const kopia = JSON.parse(JSON.stringify(firma));
kopia.adres.miasto = "Krakow";

console.log(firma.adres.miasto); // "Poznan" - NIEZMIENIONY
console.log(kopia.adres.miasto); // "Krakow"

const trudne = {
  funkcja: () => 1,
  brak: undefined,
  data: new Date(2024, 0, 1),
  tekst: "ok"
};

console.log(JSON.stringify(trudne));
// '{"data":"2024-01-01T00:00:00.000Z","tekst":"ok"}'
// funkcja: ZNIKNELA calkowicie (klucz pominiety)
// brak (undefined): ZNIKL calkowicie (klucz pominiety)
// data: skonwertowana do stringa formatu ISO
// tekst: bez zmian

const zamowienie = { id: 5, produkty: ["chleb", "mleko"], suma: 12.5 };
const json = JSON.stringify(zamowienie);
console.log(json.length); // dlugosc stringu (np. 42)

const sparsowane = JSON.parse(json);
console.log(sparsowane.produkty.length); // 2

const zamowienie = { id: 1, stworzono: new Date() };
const kopia = JSON.parse(JSON.stringify(zamowienie));

console.log(kopia.stworzono instanceof Date); // false - BLEDNIE, to teraz zwykly string

const zamowienie = { id: 1, stworzono: new Date() };
const kopia = structuredClone(zamowienie);

console.log(kopia.stworzono instanceof Date); // true - POPRAWNIE

