// '{"a":null,"b":null,"c":5}' - NaN i Infinity zamienione na null

function zapiszDoLocalStorage(klucz, wartosc) {
  return JSON.stringify(wartosc);
}

console.log(zapiszDoLocalStorage("dane", { a: 1 })); // '{"a":1}'

const a = { x: 1, y: 2 };
const b = { x: 1, y: 2 };

console.log(a === b); // false - rozne referencje
console.log(JSON.stringify(a) === JSON.stringify(b)); // true - identyczna zawartosc jako tekst

const dane = { a: { b: { c: 42 } } };
const kopia = JSON.parse(JSON.stringify(dane));
kopia.a.b.c = 999;

console.log(dane.a.b.c);  // 42 - NIEZMIENIONY
console.log(kopia.a.b.c); // 999

const zamowienia = [{ id: 1, suma: 100 }, { id: 2, suma: 200 }];
const json = JSON.stringify(zamowienia);
const sparsowane = JSON.parse(json);
const lacznaSuma = sparsowane.reduce((s, z) => s + z.suma, 0);

console.log(lacznaSuma); // 300

const obiekt = { dane: [{ a: 1, f: () => 1 }, { a: 2 }] };
const sparsowany = JSON.parse(JSON.stringify(obiekt));

console.log(sparsowany.dane[0]); // { a: 1 } - funkcja f ZNIKNELA
console.log("f" in sparsowany.dane[0]); // false

function bezpiecznieSparsuj(tekst, domyslna) {
  try {
    return JSON.parse(tekst);
  } catch {
    return domyslna;
  }
}

console.log(bezpiecznieSparsuj('{"a":1}', {})); // { a: 1 }
console.log(bezpiecznieSparsuj("zle dane", {})); // {}

const punkty = { x: 1, y: 2 };
const kompaktowy = JSON.stringify(punkty);
const sformatowany = JSON.stringify(punkty, null, 2);

console.log(kompaktowy.length < sformatowany.length); // true

const mieszana = [1, "dwa", true, null, { a: 1 }];
const sparsowana = JSON.parse(JSON.stringify(mieszana));

console.log(sparsowana); // [1, 'dwa', true, null, { a: 1 }] - wszystko zachowane

function porownajObiekty(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}

console.log(porownajObiekty({ x: 1, y: 2 }, { x: 1, y: 2 })); // true
console.log(porownajObiekty({ x: 1 }, { x: 2 })); // false

const ustawienia = { motyw: "ciemny", jezyk: "pl" };
const sparsowane = JSON.parse(JSON.stringify(ustawienia));
console.log(sparsowane === ustawienia); // false

const tekst = "[[1,2],[3,4],[5,6]]";
const zagniezdzone = JSON.parse(tekst);
const splaszczone = zagniezdzone.flat();
console.log(splaszczone); // [1, 2, 3, 4, 5, 6]

function glebokaKopiaProsta(obiekt) {
  return JSON.parse(JSON.stringify(obiekt));
}

const oryginal = { a: { b: 1 } };
const kopia = glebokaKopiaProsta(oryginal);
kopia.a.b = 999;

console.log(oryginal.a.b); // 1 - NIEZMIENIONY
console.log(kopia.a.b);    // 999

